create table public.damage_claims (id uuid primary key default gen_random_uuid(), store_id uuid not null, return_id uuid not null, status text not null default 'open' check(status in ('open','under_review','accepted','denied','closed')), description text not null, evidence jsonb not null default '[]'::jsonb, resolution_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,return_id) references public.returns(store_id,id) on delete cascade);
